solution.code:
#include <stdio.h>

struct Pair {
    int id;
    double score;
};

int main() {
    struct Pair p;
    p.id = 7;
    p.score = 2.5;
    printf("id=%d score=%.1f\n", p.id, p.score);
    return 0;
}
